source('R/00_common.R')
reg<-readRDS(P('mapping_and_QC/figure_registry.rds'))
orig<-readLines(P('author_inputs/Manuscript_author_revised_EN.md'),warn=FALSE)
ls<-match('## Figure legends',orig);rr<-match('## References',orig)
stopifnot(!is.na(ls),!is.na(rr),rr>ls)
body<-paste(orig[seq_len(ls-1L)],collapse='\n')
refs<-orig[rr:length(orig)]
original_body<-body
once<-function(x,old,new){stopifnot(length(gregexpr(old,x,fixed=TRUE)[[1]])==1L,grepl(old,x,fixed=TRUE));sub(old,new,x,fixed=TRUE)}
old<-paste0('CHKB-DT, RHBDF1 and TBC1D20 were the highest-ranked primary EXON associations, with adjusted coefficients of -6.353, -5.920 and -4.848, respectively. Their participant-level distributions show a similar shift in both cognitive-disease groups relative to HC (Fig. 4A1-A3).')
approved<-paste0('Among the primary EXON associations, CHKB-DT, RHBDF1 and TBC1D20 ranked highest by the adjusted pooled contrast. Their participant-level distributions showed a similar shift in both cognitive-disease groups relative to HC (Fig. 2E1-E3), illustrating that the leading exonic signal was shared across the two disease groups rather than confined to the Core 1-positive group. Their adjusted coefficients were -6.353, -5.920 and -4.848, respectively.')
body<-once(body,old,approved)
# Simultaneous citation replacement avoids chained old-to-new identifier changes.
cm<-c('Fig. 2E,G'='Fig. 2F,H','Fig. 2F'='Fig. 2G','Fig. 2H,I'='Supplementary Fig. S9','Fig. 4B'='Fig. 4A','Fig. 4C'='Fig. 4B','Supplementary Fig. S25A'='Supplementary Fig. S2','Supplementary Figs. S3 and S25B'='Supplementary Fig. S3','Supplementary Fig. S24'='Supplementary Fig. S15','Supplementary Fig. S12'='Supplementary Fig. S19','Supplementary Figs. S16-S18'='Supplementary Figs. S22-S24','Supplementary Fig. S11'='Supplementary Fig. S25')
for(i in seq_along(cm))body<-gsub(names(cm)[i],paste0('__CITE_',i,'__'),body,fixed=TRUE)
for(i in seq_along(cm))body<-gsub(paste0('__CITE_',i,'__'),unname(cm[i]),body,fixed=TRUE)
body<-gsub('Supplementary Fig. S7','Supplementary Fig. S10',body,fixed=TRUE)
oldsen<-'Age-stratified, age/sex-matched, AV45-only and PET-CSF-discordance sensitivity analyses are provided in Supplementary Figs. S7 and S19-S22.'
newsen<-'Biomarker-restricted and age/sex-matched analyses, followed by age-stratified analyses of GENE, TSS200, INTRON and EXON, are provided in Supplementary Figs. S10-S14.'
body<-once(body,oldsen,newsen)
body<-once(body,'The direction of the primary disease associations was highly stable when cross-gene shared intervals were removed and under alternative detection thresholds (Supplementary Fig. S9).','The direction of the primary disease associations remained highly concordant after removal of cross-gene shared intervals and across alternative detection and blood-cell-adjusted analyses (Supplementary Fig. S9).')
anchor<-'Rather, within the resolution and sample size of this cohort, the dominant blood SSB pattern was more strongly aligned with the presence of cognitive disease than with the Core 1 biomarker distinction.'
body<-once(body,anchor,paste(anchor,'The full regional contrasts and complementary shared-set summaries are provided in Supplementary Figs. S4-S7. The participant-level organization of the ranked EXON associations is shown in Supplementary Fig. S8.'))
anchor<-'The resulting profiles therefore provide a map of where SSB signal is concentrated in the assay while avoiding the assumption that the largest annotation-summed peak represents the highest intrinsic breakpoint probability.'
body<-once(body,anchor,paste(anchor,'Complementary transcript-position profiles, adjusted regional contrasts and annotation-length checks are shown in Supplementary Figs. S16-S18.'))
anchor<-'The consistency of the GENE, INTRON and EXON results indicates that the source-associated signal is distributed across many related genomic representations rather than being dependent on a single regional definition.'
body<-once(body,anchor,paste(anchor,'Additional model diagnostics and feature-selection summaries are provided in Supplementary Fig. S20.'))
anchor<-'Taken together with the direct differential analysis, these results indicate that the dominant SSB signature is not a stable surrogate for Core 1 biomarker status in the present cohort.'
body<-once(body,anchor,paste0(anchor,'\n\nThe same overall pattern was evident in the precision-recall curves, repetition-specific AUCs and calibration analyses (Fig. 4C,D,H).'))
body<-once(body,'Similar patterns were seen across the other annotation spaces, and broader clinical correlations','Similar patterns were seen across the other annotation spaces (Supplementary Fig. S21), and broader clinical correlations')

mainleg<-list()
for(i in c(1L,3L))mainleg[[paste0('Figure',i)]]<-orig[grep(paste0('^\\*\\*Figure ',i,' [|]'),orig)]
mainleg$Figure2<-paste0('**Figure 2 | Genomic SSB associations shared across cognitive disease and examined against Core 1 pathology.** ',
'**A-D**, GENE, TSS200, INTRON and EXON volcano plots for the combined cognitive-disease group versus HC (259 participants with complete covariates). EXON was the primary feature space; GENE was the principal sensitivity space, with INTRON and TSS200 complementary. Axes show adjusted log2(1+SSB_LPKM) differences and -log10 nominal P values. Colors identify higher or lower signals passing within-space Benjamini-Hochberg correction at 0.05; dashed lines mark nominal P=0.05. ',
'**E1-E3**, Participant-level distributions for CHKB-DT, RHBDF1 and TBC1D20, respectively, in HC (n=144), Core 1-positive AD pathology (AD, n=89) and Core 1-negative cognitive disorders (Other, n=28). Boxes show medians and interquartile ranges, whiskers extend to observations within 1.5 interquartile ranges, and points represent participants. Brackets show nominal two-sided P values from adjusted limma contrasts fitted in the 259 complete cases. ',
'**F**, Shared and threshold-specific primary EXON sets from the two pathology-group comparisons with HC. Shared associations passed correction in both comparisons and had concordant directions. **G**, Higher and lower association counts for all three prespecified contrasts in the four annotation spaces. **H**, EXON effects for the two pathology-defined groups relative to HC, among features significant in at least one HC comparison. The diagonal is a reference line. Models included age, sex, log10 complete-library SSB yield and poly(A)-filter retention. The direct AD-Other contrast provides the test of pathology-group differences; significance in one HC contrast alone does not establish such a difference.')
mainleg$Figure4<-paste0('**Figure 4 | Internal discrimination and clinical relationships.** ',
'**A**, Receiver operating characteristic (ROC) curves for four independently trained regional source models distinguishing HC (n=142) from the combined cognitive-disease group (n=117). **B**, ROC curves for the Core 1 pathology task, comparing AD (n=89) with Other (n=28). Curves use each participant’s mean of five outer-held-out probabilities from five-fold nested cross-validation repeated five times, with four-fold inner tuning. ',
'**C**, Pathology-task precision-recall curves; the dashed line indicates the observed positive-class fraction, 89/117. **D**, AUCs from the five validation repetitions for each region and task. Repetitions reuse participants and summarize internal stability. ',
'**E**, Primary EXON source-model held-out probability versus contemporaneous observed MMSE in 100 cognitive-disease participants; the subtitle reports the two-sided Spearman correlation. **F**, Adjusted MMSE coefficients and 95% confidence intervals per 0.1 increase in held-out source probability for the four annotation spaces (n=100 each). **G**, Prespecified clinical correlations; row labels give observed paired sample sizes, cell text gives nominal two-sided Spearman P values, and color represents rho. **H**, Internal source-model calibration; legend values are Brier scores and each point summarizes a probability bin. All preprocessing, feature selection and tuning were fitted within training folds. Clinical adjusted models included age, sex, log10 library yield and poly(A)-filter retention; complete multiplicity-adjusted results accompany the source data.')
mainleg<-mainleg[paste0('Figure',1:4)]
nold<-function(id){p<-read_source(id,'participants');if('sample_id'%in%names(p))uniqueN(p$sample_id)else NA_integer_}
sup<-list()
sup$S1<-'**A**, Clinical-record eligibility and sequencing linkage leading to the final cohort of 261 participants. **B**, Availability of selected observed clinical measurements; each cell gives missing/total participants. **C**, Reviewed AV45 evidence availability. Unavailable testing in HC is not a negative biomarker result. **D**, Reviewed clinical stages among the 89 Core 1-positive participants; unspecified stages remain separate. The final groups were HC (n=144), AD (n=89) and Other (n=28).'
sup$S2<-'Age/sex-adjusted and fully adjusted pooled disease-source effects on regional log2(Ri+1), expressed as ratios of Ri+1 with 95% confidence intervals. The cohort-relative reference was fixed across regions and groups. Full adjustment included log10 complete-library SSB yield and poly(A)-filter retention. Models used 259 complete cases: 142 HC and 117 cognitive-disease participants.'
sup$S3<-'Adjusted regional age summaries in 259 participants. **A**, Age-by-source interactions for median log signal. **B**, Age coefficients for median log signal. **C**, Age coefficients for detection fraction. **D**, Age-by-source interactions for mean log signal. **E**, Mean-log-signal age coefficients per decade. Points and horizontal lines show coefficients and 95% confidence intervals; dashed lines mark zero. Models included the specified source, age, sex and technical covariates. The complete four-region test families are provided in Supplementary Data 1.'
for(i in 4:6){ct<-c('Core 1-positive AD pathology versus HC','Core 1-negative cognitive disorders versus HC','Core 1-positive versus Core 1-negative cognitive disorders')[i-3];sup[[paste0('S',i)]]<-paste0('**A-D**, ',ct,' feature associations in GENE, TSS200, INTRON and EXON, respectively. Models used the common three-group complete-case cohort (HC 142, AD 89, Other 28; total n=259). The horizontal axis is the adjusted log2(1+SSB_LPKM) difference and the vertical axis is -log10 nominal P. Colors identify higher or lower signals passing within-space Benjamini-Hochberg correction; dashed lines mark nominal P=0.05. Each region used a common tested feature set for the three contrasts. Models adjusted age, sex, log10 library yield and poly(A)-filter retention.')}
sup$S7<-'**A**, The three highest-ranked direct-pathology coefficients in each annotation space, ordered by adjusted P, absolute effect and gene ID; points and lines show coefficients and 95% confidence intervals from the three-group model (n=259). **B-D**, Shared and threshold-specific GENE, TSS200 and INTRON associations, respectively. Shared associations passed correction in both HC contrasts with the same direction. Counts for each direct AD-Other contrast are shown alongside the HC-defined sets. Threshold-specific membership does not itself test a difference between pathology groups; direct-contrast results are reported separately.'
sup$S8<-'Twelve highest-ranked primary EXON associations across all 261 participants, ordered by adjusted P, absolute effect and gene ID. Participants are grouped HC, AD and Other, then ordered by age and coded identifier. Color shows within-feature Z scores, clipped at -3 and 3 for display. Unscaled values and the full feature ranking are retained in the source data. This is a cohort-derived visualization of the association map.'
sup$S9<-'**A**, Retention of the direction and corrected association status of broad disease associations after removal of intervals shared between genes (n=259). Bars distinguish primary discoveries, directionally concordant results and concordant results retaining correction. **B**, Blood-cell-adjusted sensitivity (n=159). **C**, Alternative 10% and 30% detection thresholds (n=259). Cells in B and C give direction concordance and corrected-association retention as percentages of the primary associations in the common tested set. The number of common tested features and all original coefficients and P values are supplied with each panel.'
sup$S10<-paste0('**A**, Pathology-classifier AUCs and conditional 95% bootstrap intervals for the full, AV45-only, PET-CSF-discordance-excluded and age/sex-matched populations. Each region was modeled independently. **B**, Feature counts passing within-space correction in the corresponding direct pathology contrasts. **C**, Observed age balance in ',nold('FigS7C'),' matched participants. Matching was without replacement, required identical sex and an age difference no greater than three years. The AV45-negative/CSF-positive participant remained in the positive group in the main analysis and was excluded, not reassigned, in the discordance sensitivity. Actual model sizes are in the source tables.')
for(i in 1:4){s<-SPACES[i];oldn<-18+i;nn<-vapply(LETTERS[1:3],function(a)nold(paste0('FigS',oldn,a)),integer(1));sup[[paste0('S',10+i)]]<-paste0('**A-C**, ',s,' associations for the combined cognitive-disease group versus HC within ages 50-59, 60-69 and at least 70 years, respectively (model n=',paste(nn,collapse=', '),'). Models adjusted continuous age within each stratum, sex and technical covariates. Volcano axes show adjusted log2(1+SSB_LPKM) differences and nominal P; colors use within-stratum Benjamini-Hochberg correction. **D**, Exact overlap of the three age-stratum association sets. Binary membership follows the order 50-59/60-69/at least 70, with 1 indicating a corrected association. Overlap describes set membership rather than an age interaction.')}
sup$S15<-'Transcript-oriented SSB density per million annotated bases across the original 13 structural classes and 150 bins in HC (n=144) and the combined cognitive-disease group (n=117). Numerator and annotated-base exposure retain transcript multiplicity. Curves show group means and shading shows pointwise 95% intervals from 2,000 participant bootstrap resamples. This exposure-normalized density is distinct from Ri.'
sup$S16<-'**A**, Mean transcript-bin counts for HC (n=144) and the combined cognitive-disease group (n=117). **B**, Exposure-normalized density in HC, AD (n=89) and Other (n=28). **C**, Profile Ri in the same three groups, using the fixed cohort GENE reference. Curves retain the 13 classes and 150 bins of the original transcript-oriented structure. Shading shows pointwise 95% intervals from 2,000 participant bootstrap resamples. Internal exon and intron bins represent concatenated transcript structures rather than one universal physical transcript.'
sup$S17<-'Adjusted effects for the 13 transcript structural classes in the three prespecified pathology contrasts. Color represents the log2(profile Ri+1) coefficient and cell text gives nominal P. Models used 259 complete cases and adjusted age, sex, log10 library yield and poly(A)-filter retention. The 39 region-level tests formed one correction family; all corresponding bin-level effects are retained in the source data.'
sup$S18<-'**A-D**, Broad disease-source coefficients versus log10(annotation-union length+1) for GENE, TSS200, INTRON and EXON, respectively. Each point represents a tested feature in the 259-participant model. Color distinguishes features passing within-space Benjamini-Hochberg correction. Region lengths were retained for bias assessment and background matching; they were not used as an additional divisor in SSB_LPKM.'
sup$S19<-'Direction-specific mapping and enrichment of the primary EXON set. **A**, The 11 higher-signal associations mapped to no STRING proteins, so enrichment was not tested for this subset. **B**, The 349 lower-signal associations mapped to 226 proteins. No term in the four prespecified categories passed provider-adjusted P<0.05 against the mapped, actually tested EXON background. The categories were GO biological process, GO cellular component, Reactome and HPO.'
sup$S20<-'**A**, Source-task precision-recall curves in 259 participants; the dashed line is the observed cognitive-disease fraction. **B**, Pathology-task calibration in 117 participants; point size denotes the number in each probability bin. **C**, Source-task AUCs with conditional 95% intervals for independent molecular, Ri and clinical models. **D**, The three most frequently selected features for each molecular region across 25 outer training fits. Selection was performed within training data; selection frequency summarizes model stability across reused participants. Exact model sizes, calibration-bin sizes and selection counts are in the source data.'
sup$S21<-'Complementary GENE, INTRON and TSS200 source-model held-out probabilities versus contemporaneous observed MMSE in 100 cognitive-disease participants. Each facet gives the observed paired n, two-sided Spearman rho and nominal P. The primary EXON scatter is shown in Figure 4E and is not repeated here. Probabilities derive from independently trained regional models.'
sup$S22<-'Observed blood-count and biochemical measures versus regional SSB summaries in cognitive-disease participants. **A,B**, Regional Ri correlations with blood counts and biochemistry. **C,D**, Mean-log-signal correlations with the same measurement families. Cells give actual paired n and nominal two-sided Spearman P; color represents rho. Missing clinical observations were not imputed. Covariate-adjusted estimates and complete correction families are supplied in Supplementary Data 1.'
sup$S23<-'Clinical relationships of the cohort-ranked EXON features CHKB-DT, RHBDF1 and TBC1D20 in cognitive-disease participants. **A**, Cognitive and functional measurements. **B**, Selected observed laboratory measurements. Cells give actual paired n and nominal two-sided Spearman P; color represents rho. Complete covariate-adjusted and multiplicity-adjusted results are provided with the source data.'
sup$S24<-'Clinical relationships of independently trained pathology-model held-out scores in **A**, the combined cognitive-disease group and **B**, the Core 1-positive subgroup. Cells show observed paired n and nominal two-sided Spearman P; color represents rho. Measurements were contemporaneous and not imputed. Adjusted and family-corrected associations accompany the figure.'
sup$S25<-paste0('Exploratory early/mild versus moderate-or-greater clinical-stage comparisons among ',nold('FigS11A'),' Core 1-positive participants with the relevant stage and covariates. **A**, Regional Ri coefficients. **B**, Representative EXON coefficients for CHKB-DT, RHBDF1 and TBC1D20. Points and lines show adjusted coefficients and 95% confidence intervals. Unspecified stages and MCI/early cognitive-disorder records were not forced into an ordinal sequence.')
stopifnot(setequal(names(sup),paste0('S',1:25)))
legends<-c('# Figure legends',unlist(lapply(paste0('Figure',1:4),function(f)c('',mainleg[[f]]))),'','# Supplementary figure legends',unlist(lapply(paste0('S',1:25),function(s)c('',paste0('**Supplementary Figure ',s,' | ',reg$titles[[s]],'.** ',sup[[s]])))))
writeLines(legends,P('manuscript/Figure_legends_EN_renumbered.md'))
writeLines(c('# Supplementary Information','',unlist(lapply(paste0('S',1:25),function(s)c('',paste0('## Supplementary Figure ',s,' | ',reg$titles[[s]]),sup[[s]]))),'','## Supplementary Data 1','Comprehensive observed clinical and grouping data, regional models, differential-association results, transcript-region effects, model performance, clinical associations and enrichment results. Sheet names identify the corresponding analysis. HC is not assumed biomarker negative. Participant-level information remains subject to institutional access and consent requirements.'),P('manuscript/Supplementary_Information.md'))
new<-c(strsplit(body,'\n',fixed=TRUE)[[1]],'## Figure legends','',unlist(lapply(paste0('Figure',1:4),function(f)c(mainleg[[f]],''))),refs)
writeLines(new,P('manuscript/Manuscript_SSB_revised_full_EN_renumbered.md'))
saveRDS(list(main=mainleg,supplementary=sup),P('mapping_and_QC/legends.rds'))
# The author-controlled sections and all decimal result tokens remain unchanged.
section<-function(x,start,end){a<-regexpr(start,x,fixed=TRUE)[1];b<-regexpr(end,x,fixed=TRUE)[1];substr(x,a,b-1)}
protected<-c('Title, Abstract, Introduction and Methods'=identical(section(original_body,'# A peripheral','## Results'),section(body,'# A peripheral','## Results')),'Discussion, Conclusion and Declarations'=identical(section(original_body,'## Discussion','## Table legend'),section(body,'## Discussion','## Table legend')),'Table legend'=identical(substring(original_body,regexpr('## Table legend',original_body,fixed=TRUE)[1]),substring(body,regexpr('## Table legend',body,fixed=TRUE)[1])),'References'=identical(refs,new[match('## References',new):length(new)]))
decimal_tokens<-function(x)sort(regmatches(x,gregexpr('(?<![[:alnum:]])[-+]?[0-9]+[.][0-9]+',x,perl=TRUE))[[1]])
protected<-c(protected,'Decimal numerical tokens'=identical(decimal_tokens(original_body),decimal_tokens(body)))
wr(data.table(check=names(protected),PASS=unname(protected)),P('mapping_and_QC/prose_and_numerical_preservation.tsv'));stopifnot(all(protected))
cat('MANUSCRIPT PASS: author prose protected; approved changes and 29 figure legends generated.\n')
